{
  "subtype": "faceted_decomposition",
  "concept": "incident_delay_reasons",
  "per_column": [
    {
      "name": "incident_category",
      "is_constitutive_facet": true,
      "role": "facet",
      "rationale": "The type/nature of the incident (connectivity, email, database) is a constitutive aspect of why delays arise -- it decomposes delay reasons by the domain of the problem."
    },
    {
      "name": "incident_complexity",
      "is_constitutive_facet": true,
      "role": "facet",
      "rationale": "Complexity of the incident (system failure, escalation required, service degradation) is an intrinsic aspect of the delay-reason concept: harder incidents contribute a distinct facet of why resolution takes longer."
    },
    {
      "name": "incident_scope",
      "is_constitutive_facet": true,
      "role": "facet",
      "rationale": "Scope/breadth of impact (individual vs system-wide vs departmental) is a genuine aspect of what makes an incident's resolution slow -- a constitutive facet of delay reasons."
    },
    {
      "name": "assigned_technician",
      "is_constitutive_facet": false,
      "role": "external_predictor",
      "rationale": "The identity of the technician is an external attribute correlated with resolution time, not an aspect OF the delay-reason concept itself. It is a predictor/actor, not a part of the reason."
    },
    {
      "name": "same_technician_closure",
      "is_constitutive_facet": false,
      "role": "external_predictor",
      "rationale": "Whether the same technician closed the incident is a process/handoff attribute correlated with delay, not a constitutive facet (an 'aspect of') the delay-reason concept."
    }
  ],
  "facet_columns": ["incident_category", "incident_complexity", "incident_scope"],
  "non_facet_columns": ["assigned_technician", "same_technician_closure"],
  "mutual_exclusivity": 0.6,
  "exhaustiveness": 0.55,
  "rationale": "Three columns (category, complexity, scope) are genuine constitutive facets that decompose the delay-reason concept into aspects of the incident itself. However, complexity and scope partially overlap (e.g., 'system_wide' scope and 'system_failure' complexity capture related severity/breadth notions), lowering mutual exclusivity. The remaining two columns (assigned_technician, same_technician_closure) are external predictors/process attributes, not facets, so they do not satisfy the meronymy claim. The facet set covers problem-type, difficulty, and impact-breadth but omits process/lifecycle aspects of delay (queueing/wait time, dependency-on-third-party, information availability), so exhaustiveness is moderate."
}

